package platform

import (
	"fmt"
	"path/filepath"
	"strings"
)

// TrustPlan renders the commands needed to install or remove a local CA from
// the system trust store and the per-user Firefox/Chromium NSS databases.
// System-store changes require elevation and should be part of the one-time
// privileged plan; NSS changes run as the user.
type TrustPlan struct {
	SystemScript string
	UserScript   string
}

// InstallTrust renders CA installation commands.
func InstallTrust(caPath string) TrustPlan {
	name := "lair-local-ca.crt"
	system := fmt.Sprintf(`#!/bin/sh
# Generated by Lair. Install the local CA into the system trust store.
set -eu
case "$1" in
  --remove)
    rm -f /usr/local/share/ca-certificates/%s /etc/pki/ca-trust/source/anchors/%s 2>/dev/null || true
    if command -v update-ca-certificates >/dev/null 2>&1; then update-ca-certificates -f >/dev/null; fi
    if command -v update-ca-trust >/dev/null 2>&1; then update-ca-trust extract >/dev/null; fi
    ;;
  *)
    install -d -m 0755 /usr/local/share/ca-certificates /etc/pki/ca-trust/source/anchors
    install -m 0644 %q /usr/local/share/ca-certificates/%s
    install -m 0644 %q /etc/pki/ca-trust/source/anchors/%s
    if command -v update-ca-certificates >/dev/null 2>&1; then update-ca-certificates >/dev/null; fi
    if command -v update-ca-trust >/dev/null 2>&1; then update-ca-trust extract >/dev/null; fi
    ;;
esac
`, name, name, caPath, name, caPath, name)

	user := fmt.Sprintf(`#!/bin/sh
# Generated by Lair. Add or remove the local CA in Firefox/Chromium NSS databases.
set -eu
ACTION="${1:---add}"
if ! command -v certutil >/dev/null 2>&1; then
  echo "certutil not found (install libnss3-tools); skipping browser trust" >&2
  exit 0
fi
add_nss() {
  [ -f "$1/cert9.db" ] || return 0
  certutil -d sql:"$1" -A -t "C,," -n lair-local-ca -i %q >/dev/null 2>&1 || true
}
remove_nss() {
  [ -f "$1/cert9.db" ] || return 0
  certutil -d sql:"$1" -D -n lair-local-ca >/dev/null 2>&1 || true
}
apply() {
  if [ "$ACTION" = "--remove" ]; then
    remove_nss "$1"
  else
    add_nss "$1"
  fi
}
# Chromium and older Firefox use a flat database; newer Firefox keeps one
# database per profile below ~/.mozilla/firefox.
for DB in "$HOME/.pki/nssdb" "$HOME/.mozilla/firefox" "$HOME/.mozilla/firefox"/*; do
  [ -d "$DB" ] || continue
  apply "$DB"
done
`, caPath)
	return TrustPlan{SystemScript: system, UserScript: user}
}

// ResolvedConfigApplies reports the resolvectl commands used to scope DNS for
// the test domain to the loopback server. These are the runtime counterpart
// to the resolved drop-in and are applied by the privileged helper.
func ResolvedConfigApplies(iface, domain string, port int) []PrivilegedAction {
	if iface == "" {
		iface = "systemd-resolved"
	}
	return []PrivilegedAction{
		{
			Description: fmt.Sprintf("route *.%s to Lair DNS on 127.0.0.1:%d", domain, port),
			Command:     []string{"resolvectl", "dns", iface, fmt.Sprintf("127.0.0.1#%d", port)},
		},
		{
			Description: fmt.Sprintf("mark *.%s as a split domain", domain),
			Command:     []string{"resolvectl", "domain", iface, "~" + strings.TrimPrefix(domain, ".")},
		},
	}
}

// CertPaths returns the canonical CA and per-site certificate locations.
func CertPaths(certsDir, site string) (caCert, caKey, siteCert, siteKey string) {
	return filepath.Join(certsDir, "ca.pem"),
		filepath.Join(certsDir, "ca-key.pem"),
		filepath.Join(certsDir, sanitize(site)+".pem"),
		filepath.Join(certsDir, sanitize(site)+"-key.pem")
}

func sanitize(s string) string {
	s = strings.TrimSuffix(s, ".")
	s = strings.ReplaceAll(s, "*.", "") // wildcard maps to the base domain
	s = strings.ReplaceAll(s, "*", "_")
	replacer := strings.NewReplacer("/", "_", "\\", "_", "..", ".")
	return replacer.Replace(s)
}
